with c as (select id from public.academy_courses where id='meteorology-forecasting-foundations'),
ch as (insert into public.academy_chapters(course_id,title,description,sort_order,published) select id,'فيزياء المحيط والاقتران بين المحيط والغلاف الجوي','تدفقات السطح والطبقة المختلطة والمحتوى الحراري والتذبذبات البحرية والظواهر الساحلية والنماذج المقترنة.',56,false from c on conflict(course_id,title) do update set description=excluded.description returning id),
u1 as (insert into public.academy_units(chapter_id,title,sort_order,published) select id,'تبادل الطاقة وديناميكية المحيط',1,false from ch on conflict(chapter_id,title) do update set sort_order=excluded.sort_order returning id),
u2 as (insert into public.academy_units(chapter_id,title,sort_order,published) select id,'التذبذبات البحرية والاقتران المناخي',2,false from ch on conflict(chapter_id,title) do update set sort_order=excluded.sort_order returning id),
d(slug,title,summary,content,ord,mins,objectives,unit_title) as (values
('air-sea-fluxes-sensible-latent','تدفقات الحرارة المحسوسة والكامنة بين البحر والجو','تبادل الطاقة عند السطح البحري','{"blocks":[{"type":"heading","text":"المفهوم العلمي"},{"type":"text","text":"تنتقل الطاقة بين المحيط والغلاف الجوي عبر تدفقات الحرارة المحسوسة والكامنة، وتتأثر بفروق الحرارة والرطوبة وسرعة الرياح وخشونة السطح. تمثل هذه التدفقات شروطاً حدية مهمة للنماذج الجوية والمحيطية."},{"type":"heading","text":"المتغيرات الأساسية"},{"type":"text","text":"يتطلب تحليل تدفقات الحرارة المحسوسة والكامنة بين البحر والجو دراسة حرارة سطح البحر والحرارة تحت السطحية والملوحة والرياح والإجهاد السطحي والتدفقات الحرارية والرطوبية ومستوى سطح البحر عند الحاجة. يجب مراعاة دقة البيانات وتواترها وعمق تمثيلها المكاني والزمني."},{"type":"heading","text":"خطوات الدراسة"},{"type":"list","items":["حدد المجال البحري والفترة والمقياس الزمني للظاهرة.","اجمع بيانات سطحية وتحت سطحية متوافقة زمنياً ومكانياً.","افحص الشذوذات والتدرجات والطبقية والتدفقات المتبادلة.","اربط الاستجابة البحرية بالتغيرات الجوية والعكس.","تحقق من النتائج بمنتج مستقل أو قياسات بحرية ووضح عدم اليقين."]},{"type":"heading","text":"مثال تطبيقي"},{"type":"example","title":"تحليل حالة اقتران بحري جوي","text":"اختر منطقة بحرية وفترة ذات تغير واضح وطبق منهج تدفقات الحرارة المحسوسة والكامنة بين البحر والجو. تتبع التسلسل الزمني للمتغيرات البحرية والجوية وحدد أي تغيرات تبدو متزامنة وأيها قد تمثل استجابة متأخرة."},{"type":"heading","text":"المهمة العملية"},{"type":"text","text":"قارن تدفقات الحرارة في حالة هواء بارد وجاف يمر فوق بحر دافئ."},{"type":"heading","text":"قيود التحليل"},{"type":"list","items":["الاعتماد على حرارة السطح دون معلومات تحت سطحية.","إهمال اختلاف الدقة والتغطية بين المنتجات.","تفسير التزامن على أنه علاقة سببية مؤكدة.","تجاهل الموسمية وخط الأساس المناخي.","إهمال عدم اليقين في التدفقات أو إعادة التحليل."]},{"type":"callout","text":"المحيط ليس مجرد حد سفلي للنموذج الجوي؛ إنه نظام متغير يخزن الطاقة ويعيد توزيعها ويتفاعل مع الغلاف الجوي على مقاييس متعددة."},{"type":"heading","text":"الخلاصة"},{"type":"text","text":"يوضح تدفقات الحرارة المحسوسة والكامنة بين البحر والجو أهمية فهم التبادل ثنائي الاتجاه بين المحيط والغلاف الجوي، وضرورة الجمع بين القياسات السطحية والعمودية والتحليل الزمني."}]}'::jsonb,7360,55,'["شرح مبادئ تدفقات الحرارة المحسوسة والكامنة بين البحر والجو","تحليل بيانات المحيط والغلاف الجوي","تفسير الاقتران وحدود الاستنتاج"]'::jsonb,'تبادل الطاقة وديناميكية المحيط'),
('bulk-aerodynamic-flux-algorithms','خوارزميات التدفق الهوائي الحجمي','معاملات التبادل والرياح والاستقرار','{"blocks":[{"type":"heading","text":"المفهوم العلمي"},{"type":"text","text":"تقدر الخوارزميات الحجمية تدفقات الزخم والحرارة والرطوبة باستخدام معاملات تبادل تعتمد على سرعة الرياح والاستقرار وخشونة السطح. تختلف الصيغ في الظروف الشديدة مثل الأعاصير والرياح الضعيفة."},{"type":"heading","text":"المتغيرات الأساسية"},{"type":"text","text":"يتطلب تحليل خوارزميات التدفق الهوائي الحجمي دراسة حرارة سطح البحر والحرارة تحت السطحية والملوحة والرياح والإجهاد السطحي والتدفقات الحرارية والرطوبية ومستوى سطح البحر عند الحاجة. يجب مراعاة دقة البيانات وتواترها وعمق تمثيلها المكاني والزمني."},{"type":"heading","text":"خطوات الدراسة"},{"type":"list","items":["حدد المجال البحري والفترة والمقياس الزمني للظاهرة.","اجمع بيانات سطحية وتحت سطحية متوافقة زمنياً ومكانياً.","افحص الشذوذات والتدرجات والطبقية والتدفقات المتبادلة.","اربط الاستجابة البحرية بالتغيرات الجوية والعكس.","تحقق من النتائج بمنتج مستقل أو قياسات بحرية ووضح عدم اليقين."]},{"type":"heading","text":"مثال تطبيقي"},{"type":"example","title":"تحليل حالة اقتران بحري جوي","text":"اختر منطقة بحرية وفترة ذات تغير واضح وطبق منهج خوارزميات التدفق الهوائي الحجمي. تتبع التسلسل الزمني للمتغيرات البحرية والجوية وحدد أي تغيرات تبدو متزامنة وأيها قد تمثل استجابة متأخرة."},{"type":"heading","text":"المهمة العملية"},{"type":"text","text":"حدد المتغيرات اللازمة لحساب تدفق الحرارة الكامنة من سطح البحر."},{"type":"heading","text":"قيود التحليل"},{"type":"list","items":["الاعتماد على حرارة السطح دون معلومات تحت سطحية.","إهمال اختلاف الدقة والتغطية بين المنتجات.","تفسير التزامن على أنه علاقة سببية مؤكدة.","تجاهل الموسمية وخط الأساس المناخي.","إهمال عدم اليقين في التدفقات أو إعادة التحليل."]},{"type":"callout","text":"المحيط ليس مجرد حد سفلي للنموذج الجوي؛ إنه نظام متغير يخزن الطاقة ويعيد توزيعها ويتفاعل مع الغلاف الجوي على مقاييس متعددة."},{"type":"heading","text":"الخلاصة"},{"type":"text","text":"يوضح خوارزميات التدفق الهوائي الحجمي أهمية فهم التبادل ثنائي الاتجاه بين المحيط والغلاف الجوي، وضرورة الجمع بين القياسات السطحية والعمودية والتحليل الزمني."}]}'::jsonb,7370,55,'["شرح مبادئ خوارزميات التدفق الهوائي الحجمي","تحليل بيانات المحيط والغلاف الجوي","تفسير الاقتران وحدود الاستنتاج"]'::jsonb,'تبادل الطاقة وديناميكية المحيط'),
('sea-surface-temperature-fronts','الجبهات الحرارية لسطح البحر','التدرجات البحرية وتأثيرها الجوي','{"blocks":[{"type":"heading","text":"المفهوم العلمي"},{"type":"text","text":"تظهر الجبهات البحرية مناطق تغير مكاني سريع في حرارة سطح البحر، وقد تؤثر في الاستقرار الجوي والضباب والحمل المحلي وتوزيع الرياح. يعتمد الأثر على اتجاه الرياح وعمق الخلط والرطوبة."},{"type":"heading","text":"المتغيرات الأساسية"},{"type":"text","text":"يتطلب تحليل الجبهات الحرارية لسطح البحر دراسة حرارة سطح البحر والحرارة تحت السطحية والملوحة والرياح والإجهاد السطحي والتدفقات الحرارية والرطوبية ومستوى سطح البحر عند الحاجة. يجب مراعاة دقة البيانات وتواترها وعمق تمثيلها المكاني والزمني."},{"type":"heading","text":"خطوات الدراسة"},{"type":"list","items":["حدد المجال البحري والفترة والمقياس الزمني للظاهرة.","اجمع بيانات سطحية وتحت سطحية متوافقة زمنياً ومكانياً.","افحص الشذوذات والتدرجات والطبقية والتدفقات المتبادلة.","اربط الاستجابة البحرية بالتغيرات الجوية والعكس.","تحقق من النتائج بمنتج مستقل أو قياسات بحرية ووضح عدم اليقين."]},{"type":"heading","text":"مثال تطبيقي"},{"type":"example","title":"تحليل حالة اقتران بحري جوي","text":"اختر منطقة بحرية وفترة ذات تغير واضح وطبق منهج الجبهات الحرارية لسطح البحر. تتبع التسلسل الزمني للمتغيرات البحرية والجوية وحدد أي تغيرات تبدو متزامنة وأيها قد تمثل استجابة متأخرة."},{"type":"heading","text":"المهمة العملية"},{"type":"text","text":"اربط خريطة جبهة حرارية بحرية بتغيرات السحب والرياح فوقها."},{"type":"heading","text":"قيود التحليل"},{"type":"list","items":["الاعتماد على حرارة السطح دون معلومات تحت سطحية.","إهمال اختلاف الدقة والتغطية بين المنتجات.","تفسير التزامن على أنه علاقة سببية مؤكدة.","تجاهل الموسمية وخط الأساس المناخي.","إهمال عدم اليقين في التدفقات أو إعادة التحليل."]},{"type":"callout","text":"المحيط ليس مجرد حد سفلي للنموذج الجوي؛ إنه نظام متغير يخزن الطاقة ويعيد توزيعها ويتفاعل مع الغلاف الجوي على مقاييس متعددة."},{"type":"heading","text":"الخلاصة"},{"type":"text","text":"يوضح الجبهات الحرارية لسطح البحر أهمية فهم التبادل ثنائي الاتجاه بين المحيط والغلاف الجوي، وضرورة الجمع بين القياسات السطحية والعمودية والتحليل الزمني."}]}'::jsonb,7380,55,'["شرح مبادئ الجبهات الحرارية لسطح البحر","تحليل بيانات المحيط والغلاف الجوي","تفسير الاقتران وحدود الاستنتاج"]'::jsonb,'تبادل الطاقة وديناميكية المحيط'),
('ocean-mixed-layer-dynamics','ديناميكية الطبقة المختلطة المحيطية','الخلط والطبقية والحرارة المختزنة','{"blocks":[{"type":"heading","text":"المفهوم العلمي"},{"type":"text","text":"تمثل الطبقة المختلطة الجزء السطحي من المحيط الذي تتقارب خصائصه بفعل الرياح والحمل والخلط. يتغير عمقها موسمياً ويحدد مقدار الحرارة المتاحة للتبادل مع الجو."},{"type":"heading","text":"المتغيرات الأساسية"},{"type":"text","text":"يتطلب تحليل ديناميكية الطبقة المختلطة المحيطية دراسة حرارة سطح البحر والحرارة تحت السطحية والملوحة والرياح والإجهاد السطحي والتدفقات الحرارية والرطوبية ومستوى سطح البحر عند الحاجة. يجب مراعاة دقة البيانات وتواترها وعمق تمثيلها المكاني والزمني."},{"type":"heading","text":"خطوات الدراسة"},{"type":"list","items":["حدد المجال البحري والفترة والمقياس الزمني للظاهرة.","اجمع بيانات سطحية وتحت سطحية متوافقة زمنياً ومكانياً.","افحص الشذوذات والتدرجات والطبقية والتدفقات المتبادلة.","اربط الاستجابة البحرية بالتغيرات الجوية والعكس.","تحقق من النتائج بمنتج مستقل أو قياسات بحرية ووضح عدم اليقين."]},{"type":"heading","text":"مثال تطبيقي"},{"type":"example","title":"تحليل حالة اقتران بحري جوي","text":"اختر منطقة بحرية وفترة ذات تغير واضح وطبق منهج ديناميكية الطبقة المختلطة المحيطية. تتبع التسلسل الزمني للمتغيرات البحرية والجوية وحدد أي تغيرات تبدو متزامنة وأيها قد تمثل استجابة متأخرة."},{"type":"heading","text":"المهمة العملية"},{"type":"text","text":"فسر اختلاف استجابة سطح البحر لموجة حر جوية عندما تكون الطبقة المختلطة عميقة أو ضحلة."},{"type":"heading","text":"قيود التحليل"},{"type":"list","items":["الاعتماد على حرارة السطح دون معلومات تحت سطحية.","إهمال اختلاف الدقة والتغطية بين المنتجات.","تفسير التزامن على أنه علاقة سببية مؤكدة.","تجاهل الموسمية وخط الأساس المناخي.","إهمال عدم اليقين في التدفقات أو إعادة التحليل."]},{"type":"callout","text":"المحيط ليس مجرد حد سفلي للنموذج الجوي؛ إنه نظام متغير يخزن الطاقة ويعيد توزيعها ويتفاعل مع الغلاف الجوي على مقاييس متعددة."},{"type":"heading","text":"الخلاصة"},{"type":"text","text":"يوضح ديناميكية الطبقة المختلطة المحيطية أهمية فهم التبادل ثنائي الاتجاه بين المحيط والغلاف الجوي، وضرورة الجمع بين القياسات السطحية والعمودية والتحليل الزمني."}]}'::jsonb,7390,55,'["شرح مبادئ ديناميكية الطبقة المختلطة المحيطية","تحليل بيانات المحيط والغلاف الجوي","تفسير الاقتران وحدود الاستنتاج"]'::jsonb,'تبادل الطاقة وديناميكية المحيط'),
('ocean-heat-content','المحتوى الحراري للمحيط','توزيع الطاقة تحت سطح البحر','{"blocks":[{"type":"heading","text":"المفهوم العلمي"},{"type":"text","text":"يقيس المحتوى الحراري كمية الطاقة المخزنة في عمود مائي حتى عمق محدد، وهو مؤشر مهم لاستدامة حرارة السطح وقدرة المحيط على دعم الأعاصير. لا يمكن استنتاجه من حرارة السطح وحدها."},{"type":"heading","text":"المتغيرات الأساسية"},{"type":"text","text":"يتطلب تحليل المحتوى الحراري للمحيط دراسة حرارة سطح البحر والحرارة تحت السطحية والملوحة والرياح والإجهاد السطحي والتدفقات الحرارية والرطوبية ومستوى سطح البحر عند الحاجة. يجب مراعاة دقة البيانات وتواترها وعمق تمثيلها المكاني والزمني."},{"type":"heading","text":"خطوات الدراسة"},{"type":"list","items":["حدد المجال البحري والفترة والمقياس الزمني للظاهرة.","اجمع بيانات سطحية وتحت سطحية متوافقة زمنياً ومكانياً.","افحص الشذوذات والتدرجات والطبقية والتدفقات المتبادلة.","اربط الاستجابة البحرية بالتغيرات الجوية والعكس.","تحقق من النتائج بمنتج مستقل أو قياسات بحرية ووضح عدم اليقين."]},{"type":"heading","text":"مثال تطبيقي"},{"type":"example","title":"تحليل حالة اقتران بحري جوي","text":"اختر منطقة بحرية وفترة ذات تغير واضح وطبق منهج المحتوى الحراري للمحيط. تتبع التسلسل الزمني للمتغيرات البحرية والجوية وحدد أي تغيرات تبدو متزامنة وأيها قد تمثل استجابة متأخرة."},{"type":"heading","text":"المهمة العملية"},{"type":"text","text":"قارن منطقتين لهما حرارة سطح متشابهة لكن محتوى حراري مختلف."},{"type":"heading","text":"قيود التحليل"},{"type":"list","items":["الاعتماد على حرارة السطح دون معلومات تحت سطحية.","إهمال اختلاف الدقة والتغطية بين المنتجات.","تفسير التزامن على أنه علاقة سببية مؤكدة.","تجاهل الموسمية وخط الأساس المناخي.","إهمال عدم اليقين في التدفقات أو إعادة التحليل."]},{"type":"callout","text":"المحيط ليس مجرد حد سفلي للنموذج الجوي؛ إنه نظام متغير يخزن الطاقة ويعيد توزيعها ويتفاعل مع الغلاف الجوي على مقاييس متعددة."},{"type":"heading","text":"الخلاصة"},{"type":"text","text":"يوضح المحتوى الحراري للمحيط أهمية فهم التبادل ثنائي الاتجاه بين المحيط والغلاف الجوي، وضرورة الجمع بين القياسات السطحية والعمودية والتحليل الزمني."}]}'::jsonb,7400,55,'["شرح مبادئ المحتوى الحراري للمحيط","تحليل بيانات المحيط والغلاف الجوي","تفسير الاقتران وحدود الاستنتاج"]'::jsonb,'تبادل الطاقة وديناميكية المحيط'),
('upper-ocean-stratification','الطبقية الحرارية والملحية للمحيط','الكثافة والحواجز الطبقية','{"blocks":[{"type":"heading","text":"المفهوم العلمي"},{"type":"text","text":"تنتج الطبقية من تغير الحرارة والملوحة مع العمق، فتؤثر في الخلط الرأسي وتبادل الطاقة. قد تحد طبقة حاجزة منخفضة الملوحة من انتقال الخلط إلى الأعماق رغم وجود تدرج حراري."},{"type":"heading","text":"المتغيرات الأساسية"},{"type":"text","text":"يتطلب تحليل الطبقية الحرارية والملحية للمحيط دراسة حرارة سطح البحر والحرارة تحت السطحية والملوحة والرياح والإجهاد السطحي والتدفقات الحرارية والرطوبية ومستوى سطح البحر عند الحاجة. يجب مراعاة دقة البيانات وتواترها وعمق تمثيلها المكاني والزمني."},{"type":"heading","text":"خطوات الدراسة"},{"type":"list","items":["حدد المجال البحري والفترة والمقياس الزمني للظاهرة.","اجمع بيانات سطحية وتحت سطحية متوافقة زمنياً ومكانياً.","افحص الشذوذات والتدرجات والطبقية والتدفقات المتبادلة.","اربط الاستجابة البحرية بالتغيرات الجوية والعكس.","تحقق من النتائج بمنتج مستقل أو قياسات بحرية ووضح عدم اليقين."]},{"type":"heading","text":"مثال تطبيقي"},{"type":"example","title":"تحليل حالة اقتران بحري جوي","text":"اختر منطقة بحرية وفترة ذات تغير واضح وطبق منهج الطبقية الحرارية والملحية للمحيط. تتبع التسلسل الزمني للمتغيرات البحرية والجوية وحدد أي تغيرات تبدو متزامنة وأيها قد تمثل استجابة متأخرة."},{"type":"heading","text":"المهمة العملية"},{"type":"text","text":"حلل مقطعاً رأسياً للحرارة والملوحة وحدد الطبقة الحاجزة المحتملة."},{"type":"heading","text":"قيود التحليل"},{"type":"list","items":["الاعتماد على حرارة السطح دون معلومات تحت سطحية.","إهمال اختلاف الدقة والتغطية بين المنتجات.","تفسير التزامن على أنه علاقة سببية مؤكدة.","تجاهل الموسمية وخط الأساس المناخي.","إهمال عدم اليقين في التدفقات أو إعادة التحليل."]},{"type":"callout","text":"المحيط ليس مجرد حد سفلي للنموذج الجوي؛ إنه نظام متغير يخزن الطاقة ويعيد توزيعها ويتفاعل مع الغلاف الجوي على مقاييس متعددة."},{"type":"heading","text":"الخلاصة"},{"type":"text","text":"يوضح الطبقية الحرارية والملحية للمحيط أهمية فهم التبادل ثنائي الاتجاه بين المحيط والغلاف الجوي، وضرورة الجمع بين القياسات السطحية والعمودية والتحليل الزمني."}]}'::jsonb,7410,55,'["شرح مبادئ الطبقية الحرارية والملحية للمحيط","تحليل بيانات المحيط والغلاف الجوي","تفسير الاقتران وحدود الاستنتاج"]'::jsonb,'تبادل الطاقة وديناميكية المحيط'),
('enso-ocean-atmosphere-feedback','التغذية الراجعة بين المحيط والجو في ENSO','التبادل الاستوائي وتغير دوران ووكر','{"blocks":[{"type":"heading","text":"المفهوم العلمي"},{"type":"text","text":"ينشأ ENSO من اقتران تغير حرارة سطح البحر في الهادئ الاستوائي مع الرياح التجارية والضغط والحمل المداري. تعزز التغذية الراجعة أو تضعف الشذوذات الأولية، وتختلف استجابة الأقاليم البعيدة."},{"type":"heading","text":"المتغيرات الأساسية"},{"type":"text","text":"يتطلب تحليل التغذية الراجعة بين المحيط والجو في ENSO دراسة حرارة سطح البحر والحرارة تحت السطحية والملوحة والرياح والإجهاد السطحي والتدفقات الحرارية والرطوبية ومستوى سطح البحر عند الحاجة. يجب مراعاة دقة البيانات وتواترها وعمق تمثيلها المكاني والزمني."},{"type":"heading","text":"خطوات الدراسة"},{"type":"list","items":["حدد المجال البحري والفترة والمقياس الزمني للظاهرة.","اجمع بيانات سطحية وتحت سطحية متوافقة زمنياً ومكانياً.","افحص الشذوذات والتدرجات والطبقية والتدفقات المتبادلة.","اربط الاستجابة البحرية بالتغيرات الجوية والعكس.","تحقق من النتائج بمنتج مستقل أو قياسات بحرية ووضح عدم اليقين."]},{"type":"heading","text":"مثال تطبيقي"},{"type":"example","title":"تحليل حالة اقتران بحري جوي","text":"اختر منطقة بحرية وفترة ذات تغير واضح وطبق منهج التغذية الراجعة بين المحيط والجو في ENSO. تتبع التسلسل الزمني للمتغيرات البحرية والجوية وحدد أي تغيرات تبدو متزامنة وأيها قد تمثل استجابة متأخرة."},{"type":"heading","text":"المهمة العملية"},{"type":"text","text":"اشرح تسلسل التفاعل بين ضعف الرياح التجارية وارتفاع حرارة شرق الهادئ وتغير الحمل."},{"type":"heading","text":"قيود التحليل"},{"type":"list","items":["الاعتماد على حرارة السطح دون معلومات تحت سطحية.","إهمال اختلاف الدقة والتغطية بين المنتجات.","تفسير التزامن على أنه علاقة سببية مؤكدة.","تجاهل الموسمية وخط الأساس المناخي.","إهمال عدم اليقين في التدفقات أو إعادة التحليل."]},{"type":"callout","text":"المحيط ليس مجرد حد سفلي للنموذج الجوي؛ إنه نظام متغير يخزن الطاقة ويعيد توزيعها ويتفاعل مع الغلاف الجوي على مقاييس متعددة."},{"type":"heading","text":"الخلاصة"},{"type":"text","text":"يوضح التغذية الراجعة بين المحيط والجو في ENSO أهمية فهم التبادل ثنائي الاتجاه بين المحيط والغلاف الجوي، وضرورة الجمع بين القياسات السطحية والعمودية والتحليل الزمني."}]}'::jsonb,7420,55,'["شرح مبادئ التغذية الراجعة بين المحيط والجو في ENSO","تحليل بيانات المحيط والغلاف الجوي","تفسير الاقتران وحدود الاستنتاج"]'::jsonb,'تبادل الطاقة وديناميكية المحيط'),
('enso-subseasonal-evolution','التطور داخل الموسمي لظاهرة ENSO','تغير الشذوذات البحرية والجوية','{"blocks":[{"type":"heading","text":"المفهوم العلمي"},{"type":"text","text":"تتطور حالات ENSO على مدى أشهر وتتأثر بموجات المحيط الاستوائية والرياح والحرارة تحت السطحية. تتطلب متابعة التطور استخدام مؤشرات متعددة لا قراءة شذوذ شهر واحد فقط."},{"type":"heading","text":"المتغيرات الأساسية"},{"type":"text","text":"يتطلب تحليل التطور داخل الموسمي لظاهرة ENSO دراسة حرارة سطح البحر والحرارة تحت السطحية والملوحة والرياح والإجهاد السطحي والتدفقات الحرارية والرطوبية ومستوى سطح البحر عند الحاجة. يجب مراعاة دقة البيانات وتواترها وعمق تمثيلها المكاني والزمني."},{"type":"heading","text":"خطوات الدراسة"},{"type":"list","items":["حدد المجال البحري والفترة والمقياس الزمني للظاهرة.","اجمع بيانات سطحية وتحت سطحية متوافقة زمنياً ومكانياً.","افحص الشذوذات والتدرجات والطبقية والتدفقات المتبادلة.","اربط الاستجابة البحرية بالتغيرات الجوية والعكس.","تحقق من النتائج بمنتج مستقل أو قياسات بحرية ووضح عدم اليقين."]},{"type":"heading","text":"مثال تطبيقي"},{"type":"example","title":"تحليل حالة اقتران بحري جوي","text":"اختر منطقة بحرية وفترة ذات تغير واضح وطبق منهج التطور داخل الموسمي لظاهرة ENSO. تتبع التسلسل الزمني للمتغيرات البحرية والجوية وحدد أي تغيرات تبدو متزامنة وأيها قد تمثل استجابة متأخرة."},{"type":"heading","text":"المهمة العملية"},{"type":"text","text":"صمم لوحة متابعة شهرية تجمع حرارة السطح والرياح ومستوى سطح البحر."},{"type":"heading","text":"قيود التحليل"},{"type":"list","items":["الاعتماد على حرارة السطح دون معلومات تحت سطحية.","إهمال اختلاف الدقة والتغطية بين المنتجات.","تفسير التزامن على أنه علاقة سببية مؤكدة.","تجاهل الموسمية وخط الأساس المناخي.","إهمال عدم اليقين في التدفقات أو إعادة التحليل."]},{"type":"callout","text":"المحيط ليس مجرد حد سفلي للنموذج الجوي؛ إنه نظام متغير يخزن الطاقة ويعيد توزيعها ويتفاعل مع الغلاف الجوي على مقاييس متعددة."},{"type":"heading","text":"الخلاصة"},{"type":"text","text":"يوضح التطور داخل الموسمي لظاهرة ENSO أهمية فهم التبادل ثنائي الاتجاه بين المحيط والغلاف الجوي، وضرورة الجمع بين القياسات السطحية والعمودية والتحليل الزمني."}]}'::jsonb,7430,55,'["شرح مبادئ التطور داخل الموسمي لظاهرة ENSO","تحليل بيانات المحيط والغلاف الجوي","تفسير الاقتران وحدود الاستنتاج"]'::jsonb,'تبادل الطاقة وديناميكية المحيط'),
('indian-ocean-dipole-dynamics','ديناميكية ثنائية قطب المحيط الهندي','تباين الحرارة بين الغرب والشرق','{"blocks":[{"type":"heading","text":"المفهوم العلمي"},{"type":"text","text":"يقيس ثنائي قطب المحيط الهندي تباين حرارة سطح البحر بين أجزائه الغربية والشرقية، ويرتبط بتغير الرياح والحمل والهطول الإقليمي. يتفاعل أحياناً مع ENSO لكنه ليس تابعاً له بصورة حتمية."},{"type":"heading","text":"المتغيرات الأساسية"},{"type":"text","text":"يتطلب تحليل ديناميكية ثنائية قطب المحيط الهندي دراسة حرارة سطح البحر والحرارة تحت السطحية والملوحة والرياح والإجهاد السطحي والتدفقات الحرارية والرطوبية ومستوى سطح البحر عند الحاجة. يجب مراعاة دقة البيانات وتواترها وعمق تمثيلها المكاني والزمني."},{"type":"heading","text":"خطوات الدراسة"},{"type":"list","items":["حدد المجال البحري والفترة والمقياس الزمني للظاهرة.","اجمع بيانات سطحية وتحت سطحية متوافقة زمنياً ومكانياً.","افحص الشذوذات والتدرجات والطبقية والتدفقات المتبادلة.","اربط الاستجابة البحرية بالتغيرات الجوية والعكس.","تحقق من النتائج بمنتج مستقل أو قياسات بحرية ووضح عدم اليقين."]},{"type":"heading","text":"مثال تطبيقي"},{"type":"example","title":"تحليل حالة اقتران بحري جوي","text":"اختر منطقة بحرية وفترة ذات تغير واضح وطبق منهج ديناميكية ثنائية قطب المحيط الهندي. تتبع التسلسل الزمني للمتغيرات البحرية والجوية وحدد أي تغيرات تبدو متزامنة وأيها قد تمثل استجابة متأخرة."},{"type":"heading","text":"المهمة العملية"},{"type":"text","text":"قارن النمط الإيجابي والسلبي لثنائي قطب المحيط الهندي من حيث توزيع الحمل."},{"type":"heading","text":"قيود التحليل"},{"type":"list","items":["الاعتماد على حرارة السطح دون معلومات تحت سطحية.","إهمال اختلاف الدقة والتغطية بين المنتجات.","تفسير التزامن على أنه علاقة سببية مؤكدة.","تجاهل الموسمية وخط الأساس المناخي.","إهمال عدم اليقين في التدفقات أو إعادة التحليل."]},{"type":"callout","text":"المحيط ليس مجرد حد سفلي للنموذج الجوي؛ إنه نظام متغير يخزن الطاقة ويعيد توزيعها ويتفاعل مع الغلاف الجوي على مقاييس متعددة."},{"type":"heading","text":"الخلاصة"},{"type":"text","text":"يوضح ديناميكية ثنائية قطب المحيط الهندي أهمية فهم التبادل ثنائي الاتجاه بين المحيط والغلاف الجوي، وضرورة الجمع بين القياسات السطحية والعمودية والتحليل الزمني."}]}'::jsonb,7440,55,'["شرح مبادئ ديناميكية ثنائية قطب المحيط الهندي","تحليل بيانات المحيط والغلاف الجوي","تفسير الاقتران وحدود الاستنتاج"]'::jsonb,'تبادل الطاقة وديناميكية المحيط'),
('atlantic-multidecadal-variability','التذبذب متعدد العقود في الأطلسي','التغير البطيء في حرارة سطح البحر','{"blocks":[{"type":"heading","text":"المفهوم العلمي"},{"type":"text","text":"تصف أنماط التغير متعدد العقود في الأطلسي تقلبات واسعة زمنياً في حرارة سطح البحر والدوران، وتتداخل معها تأثيرات الهباء والانبعاثات والتقلب الداخلي. يصعب فصل المكونات دون سجلات طويلة وتحليل إحصائي حذر."},{"type":"heading","text":"المتغيرات الأساسية"},{"type":"text","text":"يتطلب تحليل التذبذب متعدد العقود في الأطلسي دراسة حرارة سطح البحر والحرارة تحت السطحية والملوحة والرياح والإجهاد السطحي والتدفقات الحرارية والرطوبية ومستوى سطح البحر عند الحاجة. يجب مراعاة دقة البيانات وتواترها وعمق تمثيلها المكاني والزمني."},{"type":"heading","text":"خطوات الدراسة"},{"type":"list","items":["حدد المجال البحري والفترة والمقياس الزمني للظاهرة.","اجمع بيانات سطحية وتحت سطحية متوافقة زمنياً ومكانياً.","افحص الشذوذات والتدرجات والطبقية والتدفقات المتبادلة.","اربط الاستجابة البحرية بالتغيرات الجوية والعكس.","تحقق من النتائج بمنتج مستقل أو قياسات بحرية ووضح عدم اليقين."]},{"type":"heading","text":"مثال تطبيقي"},{"type":"example","title":"تحليل حالة اقتران بحري جوي","text":"اختر منطقة بحرية وفترة ذات تغير واضح وطبق منهج التذبذب متعدد العقود في الأطلسي. تتبع التسلسل الزمني للمتغيرات البحرية والجوية وحدد أي تغيرات تبدو متزامنة وأيها قد تمثل استجابة متأخرة."},{"type":"heading","text":"المهمة العملية"},{"type":"text","text":"ناقش حدود إسناد تغير مطري إقليمي إلى نمط متعدد العقود وحده."},{"type":"heading","text":"قيود التحليل"},{"type":"list","items":["الاعتماد على حرارة السطح دون معلومات تحت سطحية.","إهمال اختلاف الدقة والتغطية بين المنتجات.","تفسير التزامن على أنه علاقة سببية مؤكدة.","تجاهل الموسمية وخط الأساس المناخي.","إهمال عدم اليقين في التدفقات أو إعادة التحليل."]},{"type":"callout","text":"المحيط ليس مجرد حد سفلي للنموذج الجوي؛ إنه نظام متغير يخزن الطاقة ويعيد توزيعها ويتفاعل مع الغلاف الجوي على مقاييس متعددة."},{"type":"heading","text":"الخلاصة"},{"type":"text","text":"يوضح التذبذب متعدد العقود في الأطلسي أهمية فهم التبادل ثنائي الاتجاه بين المحيط والغلاف الجوي، وضرورة الجمع بين القياسات السطحية والعمودية والتحليل الزمني."}]}'::jsonb,7450,55,'["شرح مبادئ التذبذب متعدد العقود في الأطلسي","تحليل بيانات المحيط والغلاف الجوي","تفسير الاقتران وحدود الاستنتاج"]'::jsonb,'تبادل الطاقة وديناميكية المحيط'),
('north-atlantic-oscillation-air-sea','تفاعل تذبذب شمال الأطلسي مع المحيط والجو','فروق الضغط ومسارات العواصف','{"blocks":[{"type":"heading","text":"المفهوم العلمي"},{"type":"text","text":"يرتبط تذبذب شمال الأطلسي بتغير فرق الضغط بين العروض شبه المدارية والقطبية، ما يؤثر في مسارات العواصف والرياح والتدفقات الحرارية البحرية. تختلف آثاره الإقليمية بحسب الموسم والحالة الخلفية."},{"type":"heading","text":"المتغيرات الأساسية"},{"type":"text","text":"يتطلب تحليل تفاعل تذبذب شمال الأطلسي مع المحيط والجو دراسة حرارة سطح البحر والحرارة تحت السطحية والملوحة والرياح والإجهاد السطحي والتدفقات الحرارية والرطوبية ومستوى سطح البحر عند الحاجة. يجب مراعاة دقة البيانات وتواترها وعمق تمثيلها المكاني والزمني."},{"type":"heading","text":"خطوات الدراسة"},{"type":"list","items":["حدد المجال البحري والفترة والمقياس الزمني للظاهرة.","اجمع بيانات سطحية وتحت سطحية متوافقة زمنياً ومكانياً.","افحص الشذوذات والتدرجات والطبقية والتدفقات المتبادلة.","اربط الاستجابة البحرية بالتغيرات الجوية والعكس.","تحقق من النتائج بمنتج مستقل أو قياسات بحرية ووضح عدم اليقين."]},{"type":"heading","text":"مثال تطبيقي"},{"type":"example","title":"تحليل حالة اقتران بحري جوي","text":"اختر منطقة بحرية وفترة ذات تغير واضح وطبق منهج تفاعل تذبذب شمال الأطلسي مع المحيط والجو. تتبع التسلسل الزمني للمتغيرات البحرية والجوية وحدد أي تغيرات تبدو متزامنة وأيها قد تمثل استجابة متأخرة."},{"type":"heading","text":"المهمة العملية"},{"type":"text","text":"حلل تغير تدفقات الحرارة والرياح فوق شمال الأطلسي بين طورين من NAO."},{"type":"heading","text":"قيود التحليل"},{"type":"list","items":["الاعتماد على حرارة السطح دون معلومات تحت سطحية.","إهمال اختلاف الدقة والتغطية بين المنتجات.","تفسير التزامن على أنه علاقة سببية مؤكدة.","تجاهل الموسمية وخط الأساس المناخي.","إهمال عدم اليقين في التدفقات أو إعادة التحليل."]},{"type":"callout","text":"المحيط ليس مجرد حد سفلي للنموذج الجوي؛ إنه نظام متغير يخزن الطاقة ويعيد توزيعها ويتفاعل مع الغلاف الجوي على مقاييس متعددة."},{"type":"heading","text":"الخلاصة"},{"type":"text","text":"يوضح تفاعل تذبذب شمال الأطلسي مع المحيط والجو أهمية فهم التبادل ثنائي الاتجاه بين المحيط والغلاف الجوي، وضرورة الجمع بين القياسات السطحية والعمودية والتحليل الزمني."}]}'::jsonb,7460,55,'["شرح مبادئ تفاعل تذبذب شمال الأطلسي مع المحيط والجو","تحليل بيانات المحيط والغلاف الجوي","تفسير الاقتران وحدود الاستنتاج"]'::jsonb,'التذبذبات البحرية والاقتران المناخي'),
('ocean-upwelling-atmospheric-effects','تأثير الرفع المحيطي في الطقس الساحلي','المياه الباردة والضباب والاستقرار','{"blocks":[{"type":"heading","text":"المفهوم العلمي"},{"type":"text","text":"ينقل الرفع المحيطي المياه الأبرد من الأعماق إلى السطح بفعل الرياح الساحلية، وقد يبرد الهواء السفلي ويعزز الاستقرار والضباب الساحلي. يتغير الأثر حسب اتجاه الساحل وشدة الرياح والموسم."},{"type":"heading","text":"المتغيرات الأساسية"},{"type":"text","text":"يتطلب تحليل تأثير الرفع المحيطي في الطقس الساحلي دراسة حرارة سطح البحر والحرارة تحت السطحية والملوحة والرياح والإجهاد السطحي والتدفقات الحرارية والرطوبية ومستوى سطح البحر عند الحاجة. يجب مراعاة دقة البيانات وتواترها وعمق تمثيلها المكاني والزمني."},{"type":"heading","text":"خطوات الدراسة"},{"type":"list","items":["حدد المجال البحري والفترة والمقياس الزمني للظاهرة.","اجمع بيانات سطحية وتحت سطحية متوافقة زمنياً ومكانياً.","افحص الشذوذات والتدرجات والطبقية والتدفقات المتبادلة.","اربط الاستجابة البحرية بالتغيرات الجوية والعكس.","تحقق من النتائج بمنتج مستقل أو قياسات بحرية ووضح عدم اليقين."]},{"type":"heading","text":"مثال تطبيقي"},{"type":"example","title":"تحليل حالة اقتران بحري جوي","text":"اختر منطقة بحرية وفترة ذات تغير واضح وطبق منهج تأثير الرفع المحيطي في الطقس الساحلي. تتبع التسلسل الزمني للمتغيرات البحرية والجوية وحدد أي تغيرات تبدو متزامنة وأيها قد تمثل استجابة متأخرة."},{"type":"heading","text":"المهمة العملية"},{"type":"text","text":"اربط رياحاً ساحلية موازية للشاطئ بتغير حرارة سطح البحر واحتمال الضباب."},{"type":"heading","text":"قيود التحليل"},{"type":"list","items":["الاعتماد على حرارة السطح دون معلومات تحت سطحية.","إهمال اختلاف الدقة والتغطية بين المنتجات.","تفسير التزامن على أنه علاقة سببية مؤكدة.","تجاهل الموسمية وخط الأساس المناخي.","إهمال عدم اليقين في التدفقات أو إعادة التحليل."]},{"type":"callout","text":"المحيط ليس مجرد حد سفلي للنموذج الجوي؛ إنه نظام متغير يخزن الطاقة ويعيد توزيعها ويتفاعل مع الغلاف الجوي على مقاييس متعددة."},{"type":"heading","text":"الخلاصة"},{"type":"text","text":"يوضح تأثير الرفع المحيطي في الطقس الساحلي أهمية فهم التبادل ثنائي الاتجاه بين المحيط والغلاف الجوي، وضرورة الجمع بين القياسات السطحية والعمودية والتحليل الزمني."}]}'::jsonb,7470,55,'["شرح مبادئ تأثير الرفع المحيطي في الطقس الساحلي","تحليل بيانات المحيط والغلاف الجوي","تفسير الاقتران وحدود الاستنتاج"]'::jsonb,'التذبذبات البحرية والاقتران المناخي'),
('coastal-sea-breeze-coupling','اقتران نسيم البحر بالظروف البحرية','التباين الحراري والدوران الساحلي','{"blocks":[{"type":"heading","text":"المفهوم العلمي"},{"type":"text","text":"ينشأ نسيم البحر من التباين الحراري بين اليابسة والبحر، ويتفاعل مع الرياح الخلفية والسحب والتضاريس. قد يتغير عمق جبهة النسيم وتوقيت تقدمها بحسب حرارة البحر واليابسة."},{"type":"heading","text":"المتغيرات الأساسية"},{"type":"text","text":"يتطلب تحليل اقتران نسيم البحر بالظروف البحرية دراسة حرارة سطح البحر والحرارة تحت السطحية والملوحة والرياح والإجهاد السطحي والتدفقات الحرارية والرطوبية ومستوى سطح البحر عند الحاجة. يجب مراعاة دقة البيانات وتواترها وعمق تمثيلها المكاني والزمني."},{"type":"heading","text":"خطوات الدراسة"},{"type":"list","items":["حدد المجال البحري والفترة والمقياس الزمني للظاهرة.","اجمع بيانات سطحية وتحت سطحية متوافقة زمنياً ومكانياً.","افحص الشذوذات والتدرجات والطبقية والتدفقات المتبادلة.","اربط الاستجابة البحرية بالتغيرات الجوية والعكس.","تحقق من النتائج بمنتج مستقل أو قياسات بحرية ووضح عدم اليقين."]},{"type":"heading","text":"مثال تطبيقي"},{"type":"example","title":"تحليل حالة اقتران بحري جوي","text":"اختر منطقة بحرية وفترة ذات تغير واضح وطبق منهج اقتران نسيم البحر بالظروف البحرية. تتبع التسلسل الزمني للمتغيرات البحرية والجوية وحدد أي تغيرات تبدو متزامنة وأيها قد تمثل استجابة متأخرة."},{"type":"heading","text":"المهمة العملية"},{"type":"text","text":"حدد كيف يتغير نسيم البحر عندما تكون حرارة سطح البحر أعلى من المعتاد."},{"type":"heading","text":"قيود التحليل"},{"type":"list","items":["الاعتماد على حرارة السطح دون معلومات تحت سطحية.","إهمال اختلاف الدقة والتغطية بين المنتجات.","تفسير التزامن على أنه علاقة سببية مؤكدة.","تجاهل الموسمية وخط الأساس المناخي.","إهمال عدم اليقين في التدفقات أو إعادة التحليل."]},{"type":"callout","text":"المحيط ليس مجرد حد سفلي للنموذج الجوي؛ إنه نظام متغير يخزن الطاقة ويعيد توزيعها ويتفاعل مع الغلاف الجوي على مقاييس متعددة."},{"type":"heading","text":"الخلاصة"},{"type":"text","text":"يوضح اقتران نسيم البحر بالظروف البحرية أهمية فهم التبادل ثنائي ا